namespace local_wizard\local\wizard\services\security;

/**
 * Stub switch of the mocked local_wizard engine: reads local_wizard's own agent_enabled, like the real engine.
 *
 * @package    mod_booking
 * @copyright  2026 Wunderbyte GmbH <info@wunderbyte.at>
 * @license    http://www.gnu.org/copyleft/gpl.html GNU GPL v3 or later
 */
class authorization_service {
    /**
     * Whether the engine is switched on.
     *
     * @return bool
     */
    public static function is_agent_engine_active(): bool {
        return !empty(get_config('local_wizard', 'agent_enabled'));
    }
}
